/**
 * Media index: a `url → {alt, caption}` snapshot of the Strapi Media Library.
 *
 * Inline Markdown images carry no relation to the Media Library, so their
 * `![alt](url)` text (often just the filename) is all the frontend sees. This
 * module builds, validates and applies a small derived index so inline images
 * render with the metadata authored in the Media Library.
 *
 * The index is generated by `scripts/media-index.ts` into
 * `public/media-index.json` and read server-side (see `mediaIndexSource.ts`).
 */

export const MEDIA_INDEX_VERSION = 1;

export type MediaIndexEntry = {
    alt?: string;
    caption?: string;
};

export type MediaIndexFile = {
    version: number;
    /** CMS origin the entries belong to, used to ignore foreign-hosted images. */
    baseUrl: string;
    generatedAt: string;
    entries: Record<string, MediaIndexEntry>;
};

/** Minimal shape of a media asset as returned by the MCP `media_list_assets` tool. */
export type MediaAssetInput = {
    url?: string | null;
    alternativeText?: string | null;
    caption?: string | null;
};

function nonEmpty(value: unknown): string | undefined {
    if (typeof value !== 'string') return undefined;
    const trimmed = value.trim();
    return trimmed === '' ? undefined : trimmed;
}

function stripLeadingSlashes(value: string): string {
    return value.replace(/^\/+/, '');
}

/**
 * Normalise an image URL to an index key (pathname without a leading slash).
 *
 * Relative URLs are always treated as CMS-relative. Absolute URLs are only
 * accepted when they share the index's origin, so an externally hosted image
 * cannot accidentally inherit a Media Library entry. Returns `null` when the
 * URL is unusable or belongs to another host.
 */
export function normalizeMediaKey(url: string, baseUrl: string): string | null {
    if (typeof url !== 'string') return null;
    const trimmed = url.trim();
    if (trimmed === '') return null;

    if (/^https?:\/\//i.test(trimmed)) {
        const parsed = URL.canParse(trimmed) ? new URL(trimmed) : null;
        const base = URL.canParse(baseUrl) ? new URL(baseUrl) : null;
        if (!parsed || !base || parsed.origin !== base.origin) return null;
        return stripLeadingSlashes(parsed.pathname) || null;
    }

    // Protocol-relative URLs point at an unknown origin.
    if (trimmed.startsWith('//')) return null;
    return stripLeadingSlashes(trimmed.split(/[?#]/)[0]) || null;
}

/**
 * Build the index from MCP media assets. Assets without a URL or with neither an
 * alt text nor a caption are skipped (they add nothing). Entries are sorted by
 * key so the serialised file stays deterministic.
 */
export function buildMediaIndex(args: {
    generatedAt: string;
    baseUrl: string;
    assets: MediaAssetInput[];
}): MediaIndexFile {
    const entries: Record<string, MediaIndexEntry> = {};
    for (const asset of args.assets) {
        if (typeof asset.url !== 'string') continue;
        const key = normalizeMediaKey(asset.url, args.baseUrl);
        if (!key) continue;
        const alt = nonEmpty(asset.alternativeText);
        const caption = nonEmpty(asset.caption);
        if (!alt && !caption) continue;
        entries[key] = {alt, caption};
    }

    const sorted: Record<string, MediaIndexEntry> = {};
    for (const key of Object.keys(entries).sort()) sorted[key] = entries[key];

    return {
        version: MEDIA_INDEX_VERSION,
        baseUrl: args.baseUrl,
        generatedAt: args.generatedAt,
        entries: sorted,
    };
}

export function serializeMediaIndex(index: MediaIndexFile): string {
    // 4-space indent to match the repository Prettier config (tabWidth: 4).
    return `${JSON.stringify(index, null, 4)}\n`;
}

function isMediaIndexEntry(value: unknown): value is MediaIndexEntry {
    if (typeof value !== 'object' || value === null) return false;
    const entry = value as Record<string, unknown>;
    return (
        (entry.alt === undefined || typeof entry.alt === 'string') &&
        (entry.caption === undefined || typeof entry.caption === 'string')
    );
}

/** Parse and validate a media index. Throws on a malformed file. */
export function parseMediaIndex(raw: string): MediaIndexFile {
    const parsed: unknown = JSON.parse(raw);
    if (typeof parsed !== 'object' || parsed === null)
        throw new Error('Media index is not an object');
    const index = parsed as Partial<MediaIndexFile>;

    if (index.version !== MEDIA_INDEX_VERSION) {
        throw new Error(
            `Unsupported media index version: ${String(index.version)}`
        );
    }
    if (
        typeof index.baseUrl !== 'string' ||
        typeof index.generatedAt !== 'string'
    ) {
        throw new Error('Media index is missing baseUrl or generatedAt');
    }
    if (typeof index.entries !== 'object' || index.entries === null) {
        throw new Error('Media index is missing entries');
    }
    for (const [key, entry] of Object.entries(index.entries)) {
        if (!isMediaIndexEntry(entry))
            throw new Error(`Media index entry "${key}" is invalid`);
    }

    return index as MediaIndexFile;
}

/** Look up the metadata for an image URL, or `null` when there is none. */
export function lookupMediaMetadata(
    index: MediaIndexFile,
    url: string
): MediaIndexEntry | null {
    const key = normalizeMediaKey(url, index.baseUrl);
    if (!key) return null;
    return index.entries[key] ?? null;
}

// ![alt](url) or ![alt](url "title")
const MARKDOWN_IMAGE_RE = /!\[([^\]]*)\]\(\s*([^\s)]+)(?:\s+"([^"]*)")?\s*\)/g;

function escapeAlt(value: string): string {
    return value
        .replace(/([\\[\]])/g, '\\$1')
        .replace(/\s+/g, ' ')
        .trim();
}

function escapeTitle(value: string): string {
    return value
        .replace(/([\\"])/g, '\\$1')
        .replace(/\s+/g, ' ')
        .trim();
}

/**
 * Rewrite inline Markdown images with Media Library metadata. The Media Library
 * wins whenever it has a value; otherwise the authored Markdown text is kept.
 * Images inside fenced code blocks are left untouched, and the function is
 * idempotent (running it twice yields the same result).
 */
export function enrichMarkdownImages(
    markdown: string,
    index: MediaIndexFile | null | undefined
): string {
    if (!index || typeof markdown !== 'string' || markdown === '')
        return markdown;

    let inCodeFence = false;
    return markdown
        .split('\n')
        .map((line) => {
            const trimmed = line.trimStart();
            if (trimmed.startsWith('```') || trimmed.startsWith('~~~')) {
                inCodeFence = !inCodeFence;
                return line;
            }
            if (inCodeFence) return line;

            return line.replace(
                MARKDOWN_IMAGE_RE,
                (match, alt: string, url: string, title?: string) => {
                    const metadata = lookupMediaMetadata(index, url);
                    if (!metadata) return match;

                    const nextAlt = escapeAlt(metadata.alt ?? alt);
                    const nextTitle = metadata.caption ?? title;
                    return nextTitle
                        ? `![${nextAlt}](${url} "${escapeTitle(nextTitle)}")`
                        : `![${nextAlt}](${url})`;
                }
            );
        })
        .join('\n');
}
